declare(strict_types=1);require __DIR__.'/app/request-supply.php';$user=require_verified();request_expire();$view=(string)($_GET['view']??'list');$id=marketplace_text($_GET,'id',36);$active='marketplace';$pageTitle=['create'=>'Create equipment request','edit'=>'Edit equipment request','detail'=>'Request workspace','respond'=>'Respond to request','offers'=>'My supply offers'][$view]??'My Requests';$types=rows('SELECT id,name FROM equipment_types ORDER BY name');$categories=rows('SELECT id,name FROM equipment_categories ORDER BY name');$subcategories=rows('SELECT id,name FROM equipment_subcategories ORDER BY name');$locations=rows("SELECT id,canonical_name,country_name FROM marketplace_locations WHERE location_type IN ('CITY','REGION','COUNTRY') ORDER BY country_name,canonical_name LIMIT 500");if($view==='edit')$request=request_owned($user,$id);elseif($view==='detail'){$request=request_owned($user,$id);$offers=rows("SELECT o.*,v.commercial_terms,v.validity_until,e.name equipment_name,org.name supplier_name FROM supply_offers o JOIN supply_offer_versions v ON v.supply_offer_id=o.id AND v.version_number=o.current_version JOIN equipment e ON e.id=o.equipment_id JOIN owners org ON org.id=o.supplier_organization_id WHERE o.request_id=? ORDER BY o.updated_at DESC",[$id]);$events=rows('SELECT ev.*,u.full_name FROM request_events ev LEFT JOIN users u ON u.id=ev.actor_user_id WHERE ev.request_id=? ORDER BY ev.created_at DESC',[$id]);}elseif($view==='respond'){$request=request_record($user,$id);if($request['organization_id']===$user['owner_id'])throw new DomainException('You cannot respond to your own request.',409);$equipment=rows('SELECT id,name,asset_code FROM equipment WHERE owner_id=? AND archived_at IS NULL ORDER BY name',[$user['owner_id']]);$listings=rows("SELECT id,asset_id,title FROM marketplace_listings WHERE organization_id=? AND listing_status<>'CLOSED' ORDER BY title",[$user['owner_id']]);}require __DIR__.'/includes/operations-header.php';?>
<nav class="lease-tabs"><a href="requests" <?= $view==='list'?'aria-current="page"':'' ?>>My Requests</a><a href="requests?view=offers" <?= $view==='offers'?'aria-current="page"':'' ?>>My Supply Offers</a><a href="marketplace-requests">Browse Requests</a></nav>
<?php if($view==='create'||$view==='edit'):?><header class="request-workspace-head"><div><p class="market-kicker">REQUEST & SUPPLY</p><h1><?= e($pageTitle) ?></h1><p>Publish a concise, time-bound equipment requirement.</p></div></header><?php require __DIR__.'/includes/request-form.php';?>
<?php elseif($view==='detail'):?><header class="request-workspace-head"><div><p class="market-kicker">REQUEST WORKSPACE</p><h1><?= e($request['title']) ?></h1><p><?= e($request['equipment_type'].' · '.$request['intent'].' · quantity '.$request['quantity_required']) ?></p></div><span class="request-badge"><?= e($request['status']) ?></span></header><section class="transaction-grid"><article><span>Location</span><strong><?= e($request['location_name']) ?></strong></article><article><span>Required</span><strong><?= e($request['required_from'].($request['required_until']?' – '.$request['required_until']:'')) ?></strong></article><article><span>Deadline</span><strong><?= e($request['response_deadline']) ?></strong></article><article><span>Version</span><strong><?= (int)$request['current_version'] ?></strong></article></section><section class="transaction-panel"><div class="agreement-actions"><?php if(in_array($request['status'],['DRAFT','OPEN'],true)):?><a class="market-button" href="requests?view=edit&id=<?= e($id) ?>">Edit request</a><?php endif;?><?php if($request['status']==='DRAFT'):?><form action="request-action" method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="request.publish"><input type="hidden" name="id" value="<?= e($id) ?>"><button>Publish</button></form><?php endif;?><details><summary>Extend deadline</summary><form action="request-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="request.extend"><input type="hidden" name="id" value="<?= e($id) ?>"><input type="datetime-local" name="response_deadline" required><button>Extend</button></form></details><?php foreach(['close'=>'Close','cancel'=>'Cancel'] as $action=>$label):?><form action="request-action" method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="request.<?= e($action) ?>"><input type="hidden" name="id" value="<?= e($id) ?>"><button><?= e($label) ?></button></form><?php endforeach;?></div></section><section class="transaction-panel"><h2>Supplier responses</h2><div class="request-offer-list"><?php foreach($offers as $offer):$terms=json_decode($offer['commercial_terms'],true);?><article><div><strong><?= e($offer['supplier_name'].' · '.$offer['equipment_name']) ?></strong><p><?= e($terms['currency'].' '.number_format((float)$terms['amount'],2).' · '.$terms['pricing_basis']) ?></p></div><div><span class="request-badge"><?= e($offer['status']) ?></span> <a href="request-offer?id=<?= e($offer['id']) ?>">Review response</a></div></article><?php endforeach;?><?php if(!$offers):?><p>No supplier responses yet.</p><?php endif;?></div></section><section class="transaction-panel"><h2>Activity</h2><div class="transaction-activity"><?php foreach($events as $event):?><article><span><?= e($event['created_at']) ?></span><strong><?= e(str_replace('_',' ',$event['event_type'])) ?></strong><small><?= e($event['full_name']??'System') ?></small></article><?php endforeach;?></div></section>
<?php elseif($view==='respond'):?><header class="request-workspace-head"><div><p class="market-kicker">RESPOND TO REQUEST</p><h1><?= e($request['title']) ?></h1><p>Use equipment your organization already manages. It does not need a public listing.</p></div></header><?php if(!$equipment):?><section class="market-empty"><h2>Register equipment before responding</h2><p>The proposed supply must have a canonical Nonagon equipment record.</p><a href="equipment?action=register">Register equipment</a></section><?php else:?><form action="request-action" method="post" enctype="multipart/form-data" class="request-form" data-safe-draft="response-<?= e($id) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="offer.create"><input type="hidden" name="request_id" value="<?= e($id) ?>"><label>Equipment<select name="equipment_id" required><option value="">Choose equipment</option><?php foreach($equipment as $item):?><option value="<?= e($item['id']) ?>"><?= e($item['name'].' · '.$item['asset_code']) ?></option><?php endforeach;?></select></label><label>Marketplace listing <small>Optional</small><select name="marketplace_listing_id"><option value="">No public listing</option><?php foreach($listings as $item):?><option value="<?= e($item['id']) ?>"><?= e($item['title']) ?></option><?php endforeach;?></select></label><label>Quantity available<input type="number" name="quantity_offered" min="1" value="1" required></label><label>Price / rate<input type="number" step="0.01" min="0.01" name="amount" required></label><label>Currency<input name="currency" value="NGN" maxlength="3" required></label><label>Pricing basis<select name="pricing_basis"><option>DAILY</option><option>HOURLY</option><option>WEEKLY</option><option>MONTHLY</option><option>PROJECT</option><option>FIXED</option></select></label><label>Available from<input type="date" name="available_from" value="<?= e($request['required_from']) ?>" required></label><label>Available until<input type="date" name="available_until" value="<?= e($request['required_until']??'') ?>"></label><label>Offer valid until<input type="datetime-local" name="validity_until" required></label><label>Security deposit<input type="number" step="0.01" min="0" name="security_deposit" value="0"></label><label class="full">Mobilization / delivery<textarea name="mobilization_delivery"></textarea></label><label class="full">Demobilization<textarea name="demobilization"></textarea></label><label>Operator terms<textarea name="operator_terms"></textarea></label><label>Maintenance responsibility<textarea name="maintenance_responsibility"></textarea></label><label>Insurance requirements<textarea name="insurance_requirements"></textarea></label><label>Technical response <small>One item per line</small><textarea name="technical_response"></textarea></label><label class="full">Technical deviations<textarea name="deviations"></textarea></label><label class="full">Notes<textarea name="notes"></textarea></label><label>Supporting document<input type="file" name="supporting_document" accept=".pdf,.docx,image/jpeg,image/png"></label><div class="full"><button name="submit" value="1" class="market-button">Submit response</button> <button>Save draft</button></div></form><?php endif;?>
<?php elseif($view==='offers'):$myOffers=rows("SELECT o.*,r.title request_title,v.commercial_terms,e.name equipment_name FROM supply_offers o JOIN marketplace_requests r ON r.id=o.request_id JOIN supply_offer_versions v ON v.supply_offer_id=o.id AND v.version_number=o.current_version JOIN equipment e ON e.id=o.equipment_id WHERE o.supplier_organization_id=? ORDER BY o.updated_at DESC",[$user['owner_id']]);?><header class="request-workspace-head"><div><p class="market-kicker">SUPPLY RESPONSES</p><h1>My Supply Offers</h1></div></header><section class="manage-table"><div class="market-table-wrap"><table><thead><tr><th>Request</th><th>Equipment</th><th>Commercial</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($myOffers as $offer):$terms=json_decode($offer['commercial_terms'],true);?><tr><td><?= e($offer['request_title']) ?></td><td><?= e($offer['equipment_name']) ?></td><td><?= e($terms['currency'].' '.number_format((float)$terms['amount'],2)) ?></td><td><?= e($offer['status']) ?></td><td><a href="request-offer?id=<?= e($offer['id']) ?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:$myRequests=rows("SELECT r.*,t.name equipment_type,(SELECT COUNT(*) FROM supply_offers o WHERE o.request_id=r.id AND o.status<>'DRAFT') response_count FROM marketplace_requests r JOIN equipment_types t ON t.id=r.equipment_type_id WHERE r.organization_id=? ORDER BY r.updated_at DESC",[$user['owner_id']]);?><header class="request-workspace-head"><div><p class="market-kicker">REQUEST & SUPPLY</p><h1>My Requests</h1><p>Manage demand published to equipment owners and suppliers.</p></div><a class="market-button" href="requests?view=create">+ Create request</a></header><section class="manage-table"><div class="market-table-wrap"><table><thead><tr><th>Request</th><th>Intent</th><th>Quantity</th><th>Deadline</th><th>Responses</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($myRequests as $item):?><tr><td><strong><?= e($item['title']) ?></strong><small><?= e($item['equipment_type']) ?></small></td><td><?= e($item['intent']) ?></td><td><?= (int)$item['quantity_required'] ?></td><td><?= e($item['response_deadline']) ?></td><td><?= (int)$item['response_count'] ?></td><td><span class="request-badge"><?= e($item['status']) ?></span></td><td><a href="requests?view=detail&id=<?= e($item['id']) ?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
